const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const seattle = ee.Geometry.Point([-122.3321, 47.6062]).buffer(1000); // Seattle center with 1km buffer
  const startDate = '2021-11-01';
  const endDate = '2021-11-30';
  const rainfallThresholdCm = 20; // cm

  // 2. Data Acquisition & Check
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
                   .filterDate(startDate, endDate)
                   .filterBounds(seattle);

  const collectionSize = await chirps.size().getInfo();

  if (collectionSize === 0) {
    console.log("No CHIRPS images found for Seattle in November 2021.");
    console.log("C1");
    return;
  }
  console.log(`CHIRPS images found: ${collectionSize}`);

  // 3. Processing & Calculation
  // Sum daily precipitation (band 'precipitation' is in mm/day)
  const totalPrecipitation = chirps.select('precipitation').sum();

  // Reduce region to get the total precipitation value for Seattle
  const meanPrecipitation = await totalPrecipitation.reduceRegion({
    reducer: ee.Reducer.mean(), // Using mean over the buffered area
    geometry: seattle,
    scale: 5000, // CHIRPS resolution is ~5.5 km, so 5000m is appropriate
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  // 4. Validation & Final Answer
  if (meanPrecipitation === null || isNaN(meanPrecipitation)) {
    console.log("Calculation failed: Precipitation value is null or NaN.");
    console.log("C3");
    return;
  }

  // Convert millimeters to centimeters
  const totalPrecipitationCm = meanPrecipitation / 10;

  // Check valid pixels (indirectly, as reduceRegion usually returns null if no pixels)
  // To explicitly check for valid pixels, we could use ee.Reducer.count()
  // But for a continuous dataset like CHIRPS over a point, if meanPrecipitation is not null,
  // we assume valid pixels were processed.

  console.log(`November 2021 total rainfall in Seattle: ${totalPrecipitationCm.toFixed(2)} cm`);

  if (totalPrecipitationCm < rainfallThresholdCm) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
